def _flatten(value):
    """Yield the non-list elements of a possibly nested list."""
    if isinstance(value, list):
        for item in value:
            yield from _flatten(item)
    else:
        yield value


def check_subset_list(list1, list2):
    """Write a function to check if a nested list is a subset of another nested list.

    Return True if every element of ``list1``, after recursively
    flattening any nested lists, occurs in ``list2``, after likewise
    recursively flattening any nested lists. Ordering and duplicates
    do not matter, as for a set subset check.
    """
    flattened_list2 = list(_flatten(list2))
    return all(item in flattened_list2 for item in _flatten(list1))
